                ex, ey = nearest_enemy
                # If enemy adjacent, step away if possible
                if abs(ex - x) <= 1 and abs(ey - y) <= 1:
                    if ex > x:
                        dx = -1
                    elif ex < x:
                        dx = 1
                    if ey > y:
                        dy = -1
                    elif ey < y:
                        dy = 1
                    return [dx, dy]

    # Fallback: try to move randomly-like within constraints using info
